// ── Helper : normaliser features JSON → texte éditable (supporte format array simple + objet multi-sections)
function _pkgFeaturesToText(featuresStr) {
  if (!featuresStr) return '';
  try {
    const parsed = JSON.parse(featuresStr);
    if (Array.isArray(parsed)) {
      // Format simple : ["feat1","feat2"] 
      return parsed.join('\n');
    } else if (typeof parsed === 'object') {
      // Format multi-sections : { "S'ÉDUQUER": ["..."], "CRÉER": ["..."] }
      const lines = [];
      for (const [section, items] of Object.entries(parsed)) {
        lines.push(`## ${section}`);
        if (Array.isArray(items)) {
          items.forEach(i => lines.push(i));
        }
        lines.push('');
      }
      return lines.join('\n').trim();
    }
  } catch(e) {}
  return featuresStr;
}

// ── Helper : convertir texte éditable → JSON features
// Supporte les sections ## Titre et les listes simples
function _pkgTextToFeatures(text) {
  const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  let hasSections = lines.some(l => l.startsWith('##'));
  if (!hasSections) {
    return JSON.stringify(lines);
  }
  // Format multi-sections
  const obj = {};
  let currentSection = null;
  for (const line of lines) {
    if (line.startsWith('## ')) {
      currentSection = line.slice(3).trim();
      obj[currentSection] = [];
    } else if (currentSection) {
      obj[currentSection].push(line);
    }
  }
  return JSON.stringify(obj);
}

