// Prévisualiser un document dans une lightbox
async function adminKycPreviewDoc(docId, fileName) {
  // Afficher un loader lightbox immédiatement
  const overlay = document.createElement('div');
  overlay.className = 'fixed inset-0 bg-black/90 z-[500] flex items-center justify-center p-4';
  overlay.innerHTML = `<div class="loader"></div>`;
  document.body.appendChild(overlay);
  overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };

  try {
    // D'abord chercher dans les docs déjà chargés (évite un appel réseau si data_b64 présent)
    let data_b64 = null, mime_type = null;
    const cached = window._currentKycAppId
      ? await apiAdmin('GET', `/kyc/application/${window._currentKycAppId}`)
      : null;
    const cachedDoc = (cached?.application?.documents || []).find(d => d.id === docId);
    if (cachedDoc?.data_b64) {
      data_b64 = cachedDoc.data_b64;
      mime_type = cachedDoc.mime_type;
    } else {
      // Fallback : route dédiée avec format=json pour récupérer data_b64
      const res = await apiAdmin('GET', `/kyc/document/${docId}/download?format=json`);
      data_b64 = res?.data_b64;
      mime_type = res?.mime_type;
    }

    if (!data_b64) {
      overlay.remove();
      showToast('Document non disponible', 'error');
      return;
    }

    const isImg = (mime_type || '').startsWith('image/');
    const isPdf = (mime_type || '') === 'application/pdf';
    const src = `data:${mime_type};base64,${data_b64}`;

    overlay.innerHTML = `
      <div class="relative max-w-4xl w-full max-h-[92vh] flex flex-col items-center gap-3">
        <div class="flex items-center justify-between w-full px-1">
          <span class="text-xs text-gray-400 truncate max-w-xs">${fileName || 'Document'}</span>
          <div class="flex items-center gap-2">
            <button onclick="adminKycDownloadDoc('${docId}','${fileName || 'document'}')"
                    class="text-xs text-blue-400 hover:text-blue-300 bg-blue-900/20 px-3 py-1.5 rounded-lg transition">
              <i class="fas fa-download mr-1"></i>Télécharger
            </button>
            <button onclick="this.closest('.fixed').remove()"
                    class="text-gray-400 hover:text-white bg-white/10 hover:bg-white/20 rounded-full w-8 h-8 flex items-center justify-center transition">
              <i class="fas fa-times"></i>
            </button>
          </div>
        </div>
        ${isImg
          ? `<img src="${src}" class="max-w-full max-h-[80vh] rounded-xl object-contain shadow-2xl">`
          : isPdf
            ? `<iframe src="${src}" class="w-full h-[80vh] rounded-xl bg-white"></iframe>`
            : `<div class="text-gray-400 text-sm">Format non prévisualisable — utilisez le bouton Télécharger.</div>`
        }
      </div>`;
  } catch(e) {
    overlay.remove();
    showToast('Erreur lors du chargement du document', 'error');
  }
}

// Télécharger un document
async function adminKycDownloadDoc(docId, fileName) {
  try {
    const res = await apiAdmin('GET',`/kyc/application/${window._currentKycAppId}`);
    const doc = (res.application?.documents||[]).find(d=>d.id===docId);
    if (!doc?.data_b64) {
      // Fallback : téléchargement direct via route dédiée
      const url = `/api/admin/kyc/document/${docId}/download`;
      const a = document.createElement('a');
      a.href = url; a.download = fileName; a.click();
      return;
    }
    const a = document.createElement('a');
    a.href = `data:${doc.mime_type||'image/jpeg'};base64,${doc.data_b64}`;
    a.download = fileName || doc.file_name || 'document';
    a.click();
  } catch(e) { showToast('Erreur téléchargement','error'); }
}

