// Télécharger tout le dossier KYC d'un membre (ZIP via JSZip CDN)
async function adminKycDownloadAll(memberId) {
  showToast('Préparation du dossier…');
  try {
    const res = await apiAdmin('GET',`/kyc/member/${memberId}/download-all`);
    const docs = res.documents || [];
    const folderName = res.folder_name || `KYC_${memberId}`;

    if (docs.length === 0) {
      showToast('Aucun document à télécharger', 'error');
      return;
    }

    // Charger JSZip si pas déjà présent
    if (!window.JSZip) {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    }

    const zip = new window.JSZip();
    const folder = zip.folder(folderName);

    for (const doc of docs) {
      if (!doc.data_b64) continue;
      const ext = (doc.mime_type || '').includes('pdf') ? 'pdf'
                : (doc.mime_type || '').includes('png') ? 'png' : 'jpg';
      const fileName = `niveau_${doc.level}_${doc.doc_type_name || doc.doc_type_id}.${ext}`;
      const byteString = atob(doc.data_b64);
      const bytes = new Uint8Array(byteString.length);
      for (let i = 0; i < byteString.length; i++) bytes[i] = byteString.charCodeAt(i);
      folder.file(fileName, bytes);
    }

    const blob = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${folderName}.zip`;
    a.click();
    URL.revokeObjectURL(url);
    showToast(`ZIP téléchargé (${docs.length} document(s))`, 'success');

  } catch(e) {
    showToast(e.error || 'Erreur téléchargement', 'error');
  }
}

// ── Onglet Niveaux & Documents ────────────────────────────────
async function adminKycLoadLevels(el) {
  el.innerHTML = '<div class="flex justify-center py-12"><div class="loader"></div></div>';
  try {
    const res = await apiAdmin('GET','/kyc/config');
    const levels   = res.levels   || [];
    const allDocs  = res.doc_types || [];
    const levelDocs= res.level_docs || [];

    el.innerHTML = `
    <div class="space-y-6">
      <div class="text-sm text-gray-400 bg-dark-800 border border-dark-600 rounded-xl px-4 py-3">
        <i class="fas fa-info-circle text-blue-400 mr-2"></i>
        Cochez/décochez les documents requis pour chaque niveau. Les modifications sont appliquées immédiatement.
        Au niveau 2+, ne remettre que les <strong>nouveaux</strong> documents (pas ceux déjà validés aux niveaux précédents).
      </div>

      ${levels.filter(l => l.id > 0).map(level => {
        const levelDocIds = levelDocs.filter(d => d.level_id === level.id);
        const enabledDocIds = new Set(levelDocIds.map(d => d.doc_type_id));
        const requiredDocIds = new Set(levelDocIds.filter(d => d.required).map(d => d.doc_type_id));
        const groupMap = {};
        levelDocIds.forEach(d => { if (d.doc_group) groupMap[d.doc_type_id] = d.doc_group; });

        const docsByCategory = {};
        allDocs.forEach(d => {
          if (!docsByCategory[d.category]) docsByCategory[d.category] = [];
          docsByCategory[d.category].push(d);
        });

        const catLabels = { identity: 'Identité', address: 'Domicile', other: 'Autres' };

        return `
        <div class="bg-dark-800 border border-dark-600 rounded-2xl p-5" id="kyc-level-panel-${level.id}">
          <div class="flex items-center justify-between mb-4">
            <div>
              <h3 class="font-bold text-white flex items-center gap-2">
                <span class="w-7 h-7 rounded-full bg-purple-600/30 border border-purple-500/50 flex items-center justify-center text-purple-400 font-bold text-sm">${level.id}</span>
                <input type="text" id="kyc-level-name-${level.id}" value="${level.name||''}"
                       class="bg-transparent text-white text-base font-bold border-b border-transparent hover:border-dark-400 focus:border-purple-500 focus:outline-none px-1 transition"
                       onblur="adminKycUpdateLevelName(${level.id})">
              </h3>
              <textarea id="kyc-level-desc-${level.id}" rows="1"
                        class="mt-1 text-xs text-gray-400 bg-transparent border-b border-transparent hover:border-dark-400 focus:border-purple-500 focus:outline-none w-full resize-none px-1 transition"
                        onblur="adminKycUpdateLevelName(${level.id})">${level.description||''}</textarea>
            </div>
            <label class="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
              <input type="checkbox" ${level.is_active?'checked':''} class="w-4 h-4 accent-purple-500"
                     onchange="adminKycToggleLevelActive(${level.id},this.checked)">
              Actif
            </label>
            <label class="flex items-center gap-2 text-xs text-gray-400 cursor-pointer ml-4">
              <input type="checkbox" ${level.liveness_required?'checked':''} class="w-4 h-4 accent-pink-500"
                     onchange="adminKycToggleLivenessRequired(${level.id},this.checked)">
              <i class="fas fa-face-smile text-pink-400"></i>
              Liveness requis
            </label>
          </div>

          ${Object.entries(docsByCategory).map(([cat, catDocs]) => `
          <div class="mb-4">
            <div class="text-xs text-gray-500 uppercase tracking-wider mb-2 font-medium">${catLabels[cat]||cat}</div>
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-2">
              ${catDocs.map(doc => {
                const isEnabled  = enabledDocIds.has(doc.id);
                const isRequired = requiredDocIds.has(doc.id);
                const docGroup   = groupMap[doc.id] || '';
                return `
                <div class="flex items-start gap-3 bg-dark-700/50 rounded-xl px-3 py-2.5 border ${isEnabled?'border-purple-500/30':'border-dark-500'}">
                  <label class="flex items-center gap-2 flex-1 cursor-pointer min-w-0">
                    <input type="checkbox" ${isEnabled?'checked':''} class="w-4 h-4 accent-purple-500 shrink-0"
                           id="kyc-doc-en-${level.id}-${doc.id}"
                           onchange="adminKycToggleDoc(${level.id},'${doc.id}',this.checked,document.getElementById('kyc-doc-req-${level.id}-${doc.id}')?.checked,document.getElementById('kyc-doc-grp-${level.id}-${doc.id}')?.value)">
                    <span class="text-sm text-white truncate">${doc.name}</span>
                  </label>
                  <div class="flex gap-2 shrink-0">
                    <label class="flex items-center gap-1 text-xs text-gray-400 cursor-pointer whitespace-nowrap">
                      <input type="checkbox" ${isRequired?'checked':''} class="w-3.5 h-3.5 accent-green-500"
                             id="kyc-doc-req-${level.id}-${doc.id}"
                             ${!isEnabled?'disabled':''}
                             onchange="adminKycToggleDoc(${level.id},'${doc.id}',document.getElementById('kyc-doc-en-${level.id}-${doc.id}').checked,this.checked,document.getElementById('kyc-doc-grp-${level.id}-${doc.id}')?.value)">
                      Obligatoire
                    </label>
                    <input type="text" id="kyc-doc-grp-${level.id}-${doc.id}" value="${docGroup}"
                           placeholder="groupe"
                           class="w-20 bg-dark-600 border border-dark-500 rounded px-1.5 py-0.5 text-xs text-gray-400 focus:outline-none focus:border-purple-500"
                           ${!isEnabled?'disabled':''}
                           onblur="adminKycToggleDoc(${level.id},'${doc.id}',document.getElementById('kyc-doc-en-${level.id}-${doc.id}').checked,document.getElementById('kyc-doc-req-${level.id}-${doc.id}')?.checked,this.value)"
                           title="Groupe (ex: id_primary, proof_address) — 1 doc du groupe requis">
                  </div>
                </div>`;
              }).join('')}
            </div>
          </div>`).join('')}

          <button onclick="adminKycSaveLevelDocs(${level.id})"
                  class="w-full mt-2 bg-purple-600/20 text-purple-400 border border-purple-500/30 hover:bg-purple-600/30 text-sm font-semibold py-2 rounded-xl transition">
            <i class="fas fa-save mr-2"></i>Enregistrer niveau ${level.id}
          </button>
        </div>`;
      }).join('')}
    </div>`;

    // Stocker l'état local pour sauvegarde
    window._kycLevelDocsState = {};
    levels.forEach(level => {
      window._kycLevelDocsState[level.id] = levelDocs
        .filter(d => d.level_id === level.id)
        .map(d => ({ doc_type_id: d.doc_type_id, required: !!d.required, doc_group: d.doc_group||'', enabled: true }));
    });

  } catch(e) {
    el.innerHTML = `<div class="text-red-400 p-4">Erreur : ${e.error||e.message}</div>`;
  }
}

function adminKycToggleDoc(levelId, docTypeId, enabled, required, docGroup) {
  if (!window._kycLevelDocsState) window._kycLevelDocsState = {};
  if (!window._kycLevelDocsState[levelId]) window._kycLevelDocsState[levelId] = [];
  const arr = window._kycLevelDocsState[levelId];
  const idx = arr.findIndex(d => d.doc_type_id === docTypeId);
  const entry = { doc_type_id: docTypeId, enabled: !!enabled, required: !!required, doc_group: docGroup||null };
  if (idx >= 0) arr[idx] = entry; else arr.push(entry);

  // Mise à jour visuelle immédiate de la ligne
  const enEl = document.getElementById(`kyc-doc-en-${levelId}-${docTypeId}`);
  const reqEl = document.getElementById(`kyc-doc-req-${levelId}-${docTypeId}`);
  const grpEl = document.getElementById(`kyc-doc-grp-${levelId}-${docTypeId}`);
  if (reqEl) reqEl.disabled = !enabled;
  if (grpEl) grpEl.disabled = !enabled;
}

async function adminKycSaveLevelDocs(levelId) {
  const docs = window._kycLevelDocsState?.[levelId] || [];
  if (docs.length === 0) return showToast('Aucune modification à enregistrer');
  try {
    await apiAdmin('PATCH',`/kyc/level/${levelId}/docs`,{ docs });
    showToast(`Niveau ${levelId} mis à jour`,'success');
  } catch(e) { showToast(e.error||'Erreur sauvegarde','error'); }
}

async function adminKycUpdateLevelName(levelId) {
  const name = document.getElementById(`kyc-level-name-${levelId}`)?.value?.trim();
  const desc = document.getElementById(`kyc-level-desc-${levelId}`)?.value?.trim();
  if (!name) return;
  try {
    await apiAdmin('PATCH',`/kyc/level/${levelId}`,{ name, description: desc||null });
  } catch(e) { /* silencieux */ }
}

async function adminKycToggleLevelActive(levelId, isActive) {
  try {
    await apiAdmin('PATCH',`/kyc/level/${levelId}`,{ is_active: isActive ? 1 : 0 });
    showToast(`Niveau ${levelId} ${isActive?'activé':'désactivé'}`);
  } catch(e) { showToast(e.error||'Erreur','error'); }
}

async function adminKycToggleLivenessRequired(levelId, required) {
  try {
    await apiAdmin('PATCH',`/kyc/level/${levelId}`,{ liveness_required: required ? 1 : 0 });
    showToast(`Liveness ${required?'activé':'désactivé'} pour le niveau ${levelId}`,'success');
  } catch(e) { showToast(e.error||'Erreur','error'); }
}

// ── Onglet Paramètres globaux ─────────────────────────────────
async function adminKycLoadConfig(el) {
  el.innerHTML = '<div class="flex justify-center py-12"><div class="loader"></div></div>';
  try {
    const res = await apiAdmin('GET','/kyc/config');
    const configs = res.configs || [];

    // Convertir en map
    const cfg = {};
    configs.forEach(c => { cfg[c.key] = { value: c.value, label: c.label, description: c.description, type: c.type }; });

    const sections = [
      {
        title: 'Conditions de retrait',
        icon: 'fa-money-bill-transfer',
        color: 'green',
        keys: [
          'withdrawal_kyc_required',
          'withdrawal_kyc_min_level',
          'withdrawal_level_0',
          'withdrawal_level_1',
          'withdrawal_level_2',
          'withdrawal_level_3',
        ]
      },
      {
        title: 'Système KYC',
        icon: 'fa-shield-halved',
        color: 'purple',
        keys: [
          'kyc_enabled',
          'max_file_size_mb',
          'review_sla_hours',
          'kyc_expiry_days',
          'max_resubmit_attempts',
        ]
      },
      {
        title: 'Détection automatique',
        icon: 'fa-robot',
        color: 'blue',
        keys: [
          'flag_duplicate_doc',
          'flag_expired_doc',
          'flag_name_mismatch',
          'auto_approve_enabled',
        ]
      },
      {
        title: 'Liveness / Vérification faciale',
        icon: 'fa-face-smile',
        color: 'pink',
        keys: [
          'kyc_liveness_enabled',
          'kyc_liveness_steps',
          'kyc_liveness_required_at',
        ]
      },
    ];

    el.innerHTML = `
    <div class="space-y-5">
      ${sections.map(section => `
      <div class="bg-dark-800 border border-dark-600 rounded-2xl p-5">
        <h3 class="font-semibold text-white mb-4 flex items-center gap-2">
          <i class="fas ${section.icon} text-${section.color}-400"></i>
          ${section.title}
        </h3>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-3">
          ${section.keys.filter(k => cfg[k]).map(key => {
            const param = cfg[key];
            const isBool = param.type === 'boolean';
            const isNum  = param.type === 'number';
            const val    = param.value;

            if (isBool) {
              return `
              <div class="flex items-center justify-between bg-dark-700 rounded-xl px-4 py-3 col-span-1">
                <div>
                  <div class="text-sm text-gray-200">${param.label}</div>
                  ${param.description ? `<div class="text-xs text-gray-500 mt-0.5">${param.description}</div>` : ''}
                </div>
                <label class="relative inline-flex items-center cursor-pointer ml-3 shrink-0">
                  <input type="checkbox" class="sr-only peer" id="kyc-cfg-${key}" ${val==='1'?'checked':''}
                         onchange="adminKycSaveConfig('${key}',this.checked?'1':'0')">
                  <div class="w-11 h-6 bg-dark-500 peer-checked:bg-${section.color}-600 rounded-full peer peer-focus:outline-none transition after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-5"></div>
                </label>
              </div>`;
            }

            return `
            <div class="bg-dark-700 rounded-xl px-4 py-3">
              <label class="text-xs text-gray-400 mb-1 block" for="kyc-cfg-${key}">${param.label}</label>
              ${param.description ? `<div class="text-xs text-gray-600 mb-1">${param.description}</div>` : ''}
              <div class="flex gap-2">
                <input type="${isNum?'number':'text'}" id="kyc-cfg-${key}" value="${val||''}" min="0"
                       class="flex-1 bg-dark-600 border border-dark-500 rounded-lg px-3 py-1.5 text-white text-sm focus:outline-none focus:border-purple-500">
                <button onclick="adminKycSaveConfig('${key}',document.getElementById('kyc-cfg-${key}').value)"
                        class="text-xs bg-${section.color}-600/20 text-${section.color}-400 border border-${section.color}-500/30 px-3 py-1.5 rounded-lg hover:bg-${section.color}-600/30 transition whitespace-nowrap">
                  Enregistrer
                </button>
              </div>
            </div>`;
          }).join('')}
        </div>
      </div>`).join('')}

      <!-- Formats acceptés -->
      ${cfg['accepted_formats'] ? `
      <div class="bg-dark-800 border border-dark-600 rounded-2xl p-5">
        <h3 class="font-semibold text-white mb-4 flex items-center gap-2">
          <i class="fas fa-file-alt text-orange-400"></i>
          Formats de fichiers acceptés
        </h3>
        <div class="space-y-2">
          ${['image/jpeg','image/png','application/pdf'].map(fmt => {
            let formats = [];
            try { formats = JSON.parse(cfg['accepted_formats'].value || '[]'); } catch(e) { formats = []; }
            const isChecked = formats.includes(fmt);
            return `
            <label class="flex items-center gap-3 bg-dark-700 rounded-xl px-4 py-3 cursor-pointer">
              <input type="checkbox" ${isChecked?'checked':''} class="w-4 h-4 accent-orange-500"
                     onchange="adminKycToggleFormat('${fmt}',this.checked)">
              <span class="text-sm text-gray-300">${fmt}</span>
              <span class="text-xs text-gray-500 ml-auto">${fmt==='image/jpeg'?'JPG':fmt==='image/png'?'PNG':fmt==='application/pdf'?'PDF':fmt}</span>
            </label>`;
          }).join('')}
        </div>
      </div>` : ''}

    </div>`;

  } catch(e) {
    el.innerHTML = `<div class="text-red-400 p-4">Erreur config : ${e.error||e.message}</div>`;
  }
}

async function adminKycSaveConfig(key, value) {
  try {
    await apiAdmin('PATCH','/kyc/config',{ key, value: String(value) });
    showToast(`"${key}" mis à jour`, 'success');
  } catch(e) { showToast(e.error||'Erreur','error'); }
}

async function adminKycToggleFormat(fmt, enabled) {
  try {
    const res = await apiAdmin('GET','/kyc/config');
    const cfgEntry = (res.configs||[]).find(c => c.key === 'accepted_formats');
    let formats = [];
    try { formats = JSON.parse(cfgEntry?.value || '[]'); } catch(e) { formats = []; }
    if (enabled && !formats.includes(fmt)) formats.push(fmt);
    if (!enabled) formats = formats.filter(f => f !== fmt);
    await apiAdmin('PATCH','/kyc/config',{ key: 'accepted_formats', value: JSON.stringify(formats) });
    showToast('Formats mis à jour');
  } catch(e) { showToast(e.error||'Erreur','error'); }
}

