function aiAgentNewSession() {
  _aiAgentSession = 'sess_' + Date.now() + '_' + Math.random().toString(36).slice(2,8);
  _aiAgentHistory = [];
  _aiAgentPendingPlan = null;
  _aiAgentWorking = false;
  const msgs = document.getElementById('ai-chat-messages');
  if (msgs) msgs.innerHTML = aiAgentWelcomeMessage();
  aiAgentSetWorking(false);
}

function aiAgentWelcomeMessage() {
  return `
    <div class="flex gap-3">
      <div class="w-8 h-8 rounded-lg bg-purple-500/20 border border-purple-500/30 flex items-center justify-center flex-shrink-0 mt-1">
        <i class="fas fa-robot text-purple-400 text-sm"></i>
      </div>
      <div class="flex-1">
        <div class="bg-dark-800 border border-dark-600 rounded-2xl rounded-tl-sm px-4 py-3 text-sm text-gray-300 space-y-2">
          <p>Bonjour, je suis votre <strong class="text-purple-400">Agent IA</strong>, spécialisé sur le plan de compensation LEADER.</p>
          <p class="text-gray-400 text-xs">Posez-moi n'importe quelle question — je consulte la base de données en direct, je vous explique ce que je trouve, et je vous demande si vous voulez que je corrige. <strong class="text-white">Rien n'est modifié sans votre accord explicite.</strong></p>
          <p class="text-gray-400 text-xs">Exemple : "Pourquoi la RS de Willy est à 0 ?" ou "Vérifie les commissions de ce mois"</p>
        </div>
        <div class="text-xs text-gray-600 mt-1"><i class="fas fa-robot mr-1"></i>Agent IA</div>
      </div>
    </div>`;
}

function aiAgentRenderHistory() {
  const msgs = document.getElementById('ai-chat-messages');
  if (!msgs) return;
  msgs.innerHTML = aiAgentWelcomeMessage();
  for (const m of _aiAgentHistory) {
    aiAgentAppendMessage(m.role, m.content);
  }
}

// Bloquer / débloquer la saisie pendant le traitement
function aiAgentSetWorking(working) {
  _aiAgentWorking = working;
  const input = document.getElementById('ai-agent-input');
  const btn = document.getElementById('ai-send-btn');
  if (input) {
    input.disabled = working;
    input.placeholder = working
      ? 'L\'agent travaille, veuillez patienter…'
      : 'Posez votre question… ex: Pourquoi la RS de Willy est à 0 ?';
    input.classList.toggle('opacity-50', working);
    input.classList.toggle('cursor-not-allowed', working);
  }
  if (btn) {
    btn.disabled = working;
    btn.classList.toggle('opacity-50', working);
    btn.innerHTML = working
      ? '<i class="fas fa-spinner fa-spin text-sm"></i>'
      : '<i class="fas fa-paper-plane text-sm"></i>';
  }
}

async function aiAgentSendSuggestion(question) {
  if (_aiAgentWorking) return;
  const input = document.getElementById('ai-agent-input');
  if (input) input.value = question;
  await aiAgentSend();
}

async function aiAgentSend() {
  if (_aiAgentWorking) return;
  const input = document.getElementById('ai-agent-input');
  const message = input?.value?.trim();
  if (!message) return;

  input.value = '';

  // Afficher le message utilisateur
  aiAgentAppendMessage('user', message);
  _aiAgentHistory.push({ role: 'user', content: message });

  // Bloquer la saisie
  aiAgentSetWorking(true);

  // Créer la bulle "en cours de traitement" avec les étapes
  const thinkingId = 'ai-thinking-' + Date.now();
  aiAgentAppendThinking(thinkingId);

  try {
    const response = await fetch('/api/admin/ai-agent/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${adminToken}`,
      },
      body: JSON.stringify({
        message,
        session_id: _aiAgentSession,
        history: _aiAgentHistory.slice(-20),
      }),
    });

    if (!response.ok) {
      throw new Error(`Erreur serveur (${response.status})`);
    }

    // Lire le stream SSE
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let finalData = null;

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (!line.startsWith('data: ')) continue;
        try {
          const evt = JSON.parse(line.slice(6));

          if (evt.type === 'step') {
            // Mettre à jour les étapes dans la bulle thinking
            aiAgentUpdateThinking(thinkingId, evt);

          } else if (evt.type === 'done') {
            finalData = evt;

          } else if (evt.type === 'error') {
            // Erreur pendant le traitement
            document.getElementById(thinkingId)?.remove();
            aiAgentAppendMessage('assistant', `**Erreur** : ${evt.message}`);
            finalData = null;
          }
        } catch {}
      }
    }

    if (finalData) {
      // Remplacer la bulle thinking par la réponse finale (in-place, sans scintillement)
      aiAgentReplaceThinkingWithMessage(thinkingId, finalData.message, {
        diagnosis: finalData.diagnosis,
        confidence: finalData.confidence,
        requires_code_fix: finalData.requires_code_fix,
        code_fix_hint: finalData.code_fix_hint,
        read_results: finalData.read_results,
        suggested_actions: finalData.suggested_actions,
        member_context: finalData.member_context,
        log_id: finalData.log_id,
        sql_queries: finalData.sql_queries,
        needs_execution: finalData.needs_execution,
      });

      _aiAgentHistory.push({ role: 'assistant', content: finalData.message });

      // Plan SQL d'écriture → PAS affiché automatiquement, géré via les actions contextuelles
      const writeQueries = (finalData.sql_queries || []).filter(q => !q.is_read_only);
      if (finalData.needs_execution && writeQueries.length > 0) {
        _aiAgentPendingPlan = { log_id: finalData.log_id, sql_queries: finalData.sql_queries };
      } else {
        _aiAgentPendingPlan = null;
        const plan = document.getElementById('ai-sql-plan');
        if (plan) { plan.innerHTML = ''; plan.classList.add('hidden'); }
      }
    } else {
      // Pas de finalData (stream vide ou déjà géré via 'error') : supprimer la bulle
      document.getElementById(thinkingId)?.remove();
    }

  } catch (err) {
    document.getElementById(thinkingId)?.remove();
    aiAgentAppendMessage('assistant', `**Erreur** : ${err.message || 'Impossible de contacter l\'Agent IA.'}`);
  } finally {
    aiAgentSetWorking(false);
    aiAgentScrollToBottom();
  }
}

// ── Construit le HTML interne d'un message assistant ─────────
function _aiAgentBuildAssistantInner(content, meta = {}) {
  // Nettoyage anti-JSON brut : si GPT a mis du JSON dans message, on extrait juste le texte
  let cleanContent = content || '';
  try {
    const parsed = JSON.parse(cleanContent);
    if (parsed && typeof parsed.message === 'string') cleanContent = parsed.message;
  } catch {}
  // Supprimer les blocs ```json ... ``` résiduels en fin de message
  cleanContent = cleanContent.replace(/```json[\s\S]*?```/gi, '').trim();

  let html = aiAgentMarkdown(cleanContent);
  let metaHtml = '';

  // Badge confiance
  if (meta.diagnosis) {
    const conf = Math.round((meta.confidence || 0) * 100);
    const confColor = conf >= 80 ? 'text-green-400' : conf >= 60 ? 'text-yellow-400' : 'text-red-400';
    metaHtml += `<div class="mt-2 pt-2 border-t border-dark-600 flex items-center gap-3 flex-wrap">
      <span class="text-xs text-gray-500 italic">${escapeHtml(meta.diagnosis)}</span>
      <span class="text-xs ${confColor} ml-auto">Confiance : ${conf}%</span>
    </div>`;
  }

  // Correction de code requise
  if (meta.requires_code_fix) {
    metaHtml += `<div class="mt-2 bg-red-900/20 border border-red-500/30 rounded-lg px-3 py-2 text-xs text-red-400">
      <i class="fas fa-code mr-1"></i> <strong>Correction de code requise</strong>${meta.code_fix_hint ? ' — ' + escapeHtml(meta.code_fix_hint) : ''}
    </div>`;
  }

  // Données DB : repliables, cachées par défaut
  if (meta.read_results && Object.keys(meta.read_results).length > 0) {
    const entries = Object.entries(meta.read_results).filter(([,rows]) => Array.isArray(rows) && rows.length > 0);
    if (entries.length > 0) {
      const uid = 'dbdata-' + Date.now();
      const totalRows = entries.reduce((s,[,r]) => s + r.length, 0);
      metaHtml += `
      <div class="mt-2">
        <button onclick="document.getElementById('${uid}').classList.toggle('hidden');this.querySelector('.chevron').classList.toggle('rotate-180')"
          class="flex items-center gap-2 text-xs text-gray-500 hover:text-gray-300 transition w-full text-left py-1">
          <i class="fas fa-database text-[10px]"></i>
          <span>${entries.length} table(s) · ${totalRows} ligne(s) récupérées</span>
          <i class="fas fa-chevron-down chevron text-[9px] ml-auto transition-transform duration-200"></i>
        </button>
        <div id="${uid}" class="hidden space-y-2 mt-1">`;
      for (const [key, rows] of entries) {
        const cols = Object.keys(rows[0]);
        metaHtml += `<div class="bg-dark-900/60 rounded-lg overflow-hidden border border-dark-700">
          <div class="px-3 py-1.5 text-xs text-gray-600 border-b border-dark-700 font-mono">${escapeHtml(key)}</div>
          <div class="overflow-x-auto">
            <table class="w-full text-xs">
              <thead><tr>${cols.map(c=>`<th class="px-2 py-1 text-left text-gray-600 font-normal border-b border-dark-700 whitespace-nowrap">${escapeHtml(c)}</th>`).join('')}</tr></thead>
              <tbody>${rows.slice(0,15).map(row=>`<tr class="border-b border-dark-800/60 hover:bg-dark-700/20">${cols.map(c=>`<td class="px-2 py-1 text-gray-400 font-mono text-[11px] whitespace-nowrap max-w-[200px] truncate">${row[c] != null ? escapeHtml(String(row[c])) : '—'}</td>`).join('')}</tr>`).join('')}</tbody>
            </table>
            ${rows.length > 15 ? `<div class="px-3 py-1 text-xs text-gray-600">… ${rows.length - 15} ligne(s) de plus</div>` : ''}
          </div>
        </div>`;
      }
      metaHtml += `</div></div>`;
    }
  }

  // Actions contextuelles
  const actions = Array.isArray(meta.suggested_actions) ? meta.suggested_actions : [];
  if (actions.length > 0) {
    const btnClass = {
      fix_db:       'bg-yellow-900/30 text-yellow-400 border-yellow-500/30 hover:bg-yellow-900/50',
      reply_ticket: 'bg-blue-900/30 text-blue-400 border-blue-500/30 hover:bg-blue-900/50',
      export:       'bg-dark-700 text-gray-300 border-dark-500 hover:bg-dark-600',
      new_query:    'bg-dark-700 text-gray-300 border-dark-500 hover:bg-dark-600',
      dismiss:      'bg-dark-700 text-gray-400 border-dark-600 hover:bg-dark-600',
    };
    // Stocker les payloads dans un registre global pour éviter les problèmes d'échappement onclick
    const actionsHtml = actions.map(a => {
      const cls = btnClass[a.type] || btnClass.dismiss;
      const regKey = '_aiAction_' + Date.now() + '_' + Math.random().toString(36).slice(2);
      window[regKey] = { id: a.id, type: a.type, payload: a.payload || {} };
      return `<button onclick="aiAgentHandleAction(window['${regKey}'].id, window['${regKey}'].type, window['${regKey}'].payload)"
        class="px-3 py-1.5 rounded-xl text-xs font-medium border transition ${cls}">
        ${a.icon ? a.icon + ' ' : ''}${escapeHtml(a.label)}
      </button>`;
    }).join('');
    metaHtml += `<div data-ai-actions class="mt-3 pt-2 border-t border-dark-700 flex flex-wrap gap-2">${actionsHtml}</div>`;
  }

  return { html, metaHtml };
}

// Remplace la bulle thinking par la réponse finale (in-place, sans recréer un nœud)
function aiAgentReplaceThinkingWithMessage(thinkingId, content, meta = {}) {
  const bubble = document.getElementById(thinkingId);
  if (!bubble) {
    aiAgentAppendMessage('assistant', content, meta);
    return;
  }
  const { html, metaHtml } = _aiAgentBuildAssistantInner(content, meta);
  bubble.innerHTML = `
    <div class="w-8 h-8 rounded-lg bg-purple-500/20 border border-purple-500/30 flex items-center justify-center flex-shrink-0 mt-1">
      <i class="fas fa-robot text-purple-400 text-sm"></i>
    </div>
    <div class="flex-1 max-w-[85%]">
      <div class="bg-dark-800 border border-dark-600 rounded-2xl rounded-tl-sm px-4 py-3 text-sm text-gray-300">
        ${html}${metaHtml}
      </div>
      <div class="text-xs text-gray-600 mt-1">
        <i class="fas fa-robot mr-1"></i>Agent IA · ${new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}
      </div>
    </div>`;
  bubble.removeAttribute('id');
  aiAgentScrollToBottom();
}

// Gestion des actions contextuelles
function aiAgentHandleAction(actionId, actionType, payload) {
  // Récupère le bouton cliqué pour le désactiver visuellement après action
  const btn = event?.target?.closest('button');

  if (actionType === 'dismiss') {
    // Cacher toute la rangée de boutons du message concerné
    const actionsRow = btn?.closest('[data-ai-actions]');
    if (actionsRow) {
      actionsRow.innerHTML = '<span class="text-xs text-gray-600 italic">✓ Compris</span>';
    } else if (btn) {
      // Fallback : chercher le parent flex contenant les boutons
      const row = btn.parentElement;
      if (row) row.innerHTML = '<span class="text-xs text-gray-600 italic">✓ Compris</span>';
    }
    return;
  }

  if (actionType === 'fix_db') {
    // Afficher le plan SQL déjà en attente
    if (_aiAgentPendingPlan) {
      aiAgentShowSQLPlan(_aiAgentPendingPlan.sql_queries, _aiAgentPendingPlan.log_id);
    } else {
      showToast('Aucun plan correctif en attente.', 'error');
    }
    return;
  }

  if (actionType === 'reply_ticket') {
    // Construire le texte du ticket (draft fourni par l'IA ou générique)
    const ticketText = payload?.draft || '';
    const memberName = payload?.member_name || 'le membre';

    showModal(`
      <div class="p-6 space-y-4">
        <div class="flex items-center justify-between">
          <h3 class="font-bold text-white flex items-center gap-2">
            <i class="fas fa-paper-plane text-blue-400"></i>
            Réponse ticket — ${escapeHtml(memberName)}
          </h3>
          <button onclick="closeModal()" class="text-gray-400 hover:text-white"><i class="fas fa-times"></i></button>
        </div>

        ${ticketText ? `
        <div class="bg-dark-700 rounded-xl border border-dark-600 p-4">
          <div class="text-xs text-gray-500 mb-2 uppercase tracking-wide">Réponse suggérée par l'Agent IA</div>
          <textarea id="ticket-draft-text" class="w-full bg-transparent text-sm text-gray-200 resize-none outline-none min-h-[140px]">${escapeHtml(ticketText)}</textarea>
        </div>
        <div class="flex gap-2">
          <button onclick="
            const t = document.getElementById('ticket-draft-text');
            navigator.clipboard.writeText(t.value).then(() => showToast('Texte copié dans le presse-papier ✓'));
          " class="flex-1 bg-blue-600 hover:bg-blue-500 text-white font-bold py-2.5 rounded-xl text-sm transition flex items-center justify-center gap-2">
            <i class="fas fa-copy"></i> Copier le texte
          </button>
          <button onclick="closeModal()" class="px-4 bg-dark-700 hover:bg-dark-600 text-gray-300 font-medium rounded-xl text-sm border border-dark-500 transition">
            Fermer
          </button>
        </div>
        ` : `
        <div class="bg-dark-700 rounded-xl border border-dark-600 p-4 text-sm text-gray-400">
          <i class="fas fa-info-circle mr-2 text-blue-400"></i>
          L'Agent IA n'a pas généré de brouillon automatique pour ce diagnostic.<br>
          <span class="text-gray-500 text-xs mt-1 block">Posez la question : <em>"Rédige la réponse ticket à envoyer à ${escapeHtml(memberName)}"</em></span>
        </div>
        <div class="flex gap-2">
          <button onclick="closeModal(); setTimeout(() => { const i = document.getElementById('ai-agent-input'); if(i){ i.value='Rédige la réponse ticket à envoyer à ${escapeHtml(memberName)} en te basant sur ton dernier diagnostic.'; i.focus(); }}, 100)"
            class="flex-1 bg-purple-600 hover:bg-purple-500 text-white font-bold py-2.5 rounded-xl text-sm transition flex items-center justify-center gap-2">
            <i class="fas fa-robot"></i> Demander à l'Agent IA
          </button>
          <button onclick="closeModal()" class="px-4 bg-dark-700 hover:bg-dark-600 text-gray-300 font-medium rounded-xl text-sm border border-dark-500 transition">Fermer</button>
        </div>
        `}
      </div>`);
    return;
  }

  if (actionType === 'new_query') {
    const input = document.getElementById('ai-agent-input');
    if (input && payload?.query) {
      input.value = payload.query;
      input.focus();
    }
    return;
  }
}

// Crée la bulle "en train de travailler" avec les étapes progressives
function aiAgentAppendThinking(id) {
  const msgs = document.getElementById('ai-chat-messages');
  if (!msgs) return;
  const div = document.createElement('div');
  div.id = id;
  div.className = 'flex gap-3';
  div.innerHTML = `
    <div class="w-8 h-8 rounded-lg bg-purple-500/20 border border-purple-500/30 flex items-center justify-center flex-shrink-0 mt-1">
      <i class="fas fa-robot text-purple-400 text-sm"></i>
    </div>
    <div class="flex-1">
      <div class="bg-dark-800 border border-purple-500/20 rounded-2xl rounded-tl-sm px-4 py-3">
        <div id="${id}-steps" class="space-y-2"></div>
      </div>
      <div class="text-xs text-gray-600 mt-1"><i class="fas fa-robot mr-1"></i>Agent IA · en cours…</div>
    </div>`;
  msgs.appendChild(div);
  aiAgentScrollToBottom();
}

// Met à jour les étapes dans la bulle thinking
function aiAgentUpdateThinking(id, evt) {
  const stepsEl = document.getElementById(`${id}-steps`);
  if (!stepsEl) return;

  // Chercher si l'étape existe déjà (même label)
  const existingSteps = stepsEl.querySelectorAll('[data-step-label]');
  let found = null;
  for (const el of existingSteps) {
    if (el.dataset.stepLabel === evt.label) { found = el; break; }
  }

  const statusIcon = evt.status === 'done' ? ''
    : evt.status === 'error' ? ''
    : `<span class="inline-flex gap-0.5 align-middle">
        <span class="w-1 h-1 bg-purple-400 rounded-full animate-bounce" style="animation-delay:0ms"></span>
        <span class="w-1 h-1 bg-purple-400 rounded-full animate-bounce" style="animation-delay:120ms"></span>
        <span class="w-1 h-1 bg-purple-400 rounded-full animate-bounce" style="animation-delay:240ms"></span>
      </span>`;

  const textColor = evt.status === 'done' ? 'text-gray-400'
    : evt.status === 'error' ? 'text-red-400'
    : 'text-gray-300';

  const sqlPreview = evt.sql_preview
    ? `<div class="mt-1 text-xs font-mono text-gray-600 bg-dark-900/50 rounded px-2 py-1 truncate max-w-xs">${escapeHtml(evt.sql_preview)}…</div>`
    : '';

  const html = `
    <div data-step-label="${escapeHtml(evt.label)}" class="flex items-start gap-2 text-xs ${textColor}">
      <span class="flex-shrink-0 mt-0.5">${statusIcon}</span>
      <span>${escapeHtml(evt.label)}${sqlPreview}</span>
    </div>`;

  if (found) {
    found.outerHTML = html;
  } else {
    stepsEl.insertAdjacentHTML('beforeend', html);
  }

  aiAgentScrollToBottom();
}

// Ajoute un message dans le chat (user ou assistant)
function aiAgentAppendMessage(role, content, meta = {}) {
  const msgs = document.getElementById('ai-chat-messages');
  if (!msgs) return;

  const isUser = role === 'user';
  const div = document.createElement('div');
  div.className = 'flex gap-3' + (isUser ? ' flex-row-reverse' : '');

  if (isUser) {
    div.innerHTML = `
      <div class="w-8 h-8 rounded-lg bg-dark-700 border border-dark-500 flex items-center justify-center flex-shrink-0 mt-1">
        <i class="fas fa-user text-gray-400 text-sm"></i>
      </div>
      <div class="flex-1 max-w-[85%] flex justify-end">
        <div>
          <div class="bg-purple-900/30 border border-purple-500/30 rounded-2xl rounded-tr-sm px-4 py-3 text-sm text-gray-300">
            ${aiAgentMarkdown(content)}
          </div>
          <div class="text-xs text-gray-600 mt-1 text-right">Vous · ${new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</div>
        </div>
      </div>`;
  } else {
    const { html, metaHtml } = _aiAgentBuildAssistantInner(content, meta);
    div.innerHTML = `
      <div class="w-8 h-8 rounded-lg bg-purple-500/20 border border-purple-500/30 flex items-center justify-center flex-shrink-0 mt-1">
        <i class="fas fa-robot text-purple-400 text-sm"></i>
      </div>
      <div class="flex-1 max-w-[85%]">
        <div class="bg-dark-800 border border-dark-600 rounded-2xl rounded-tl-sm px-4 py-3 text-sm text-gray-300">
          ${html}${metaHtml}
        </div>
        <div class="text-xs text-gray-600 mt-1"><i class="fas fa-robot mr-1"></i>Agent IA · ${new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</div>
      </div>`;
  }

  msgs.appendChild(div);
  aiAgentScrollToBottom();
}

// Panneau de validation du plan SQL d'écriture
function aiAgentShowSQLPlan(queries, logId) {
  const planEl = document.getElementById('ai-sql-plan');
  if (!planEl) return;

  const writeQueries = queries.filter(q => !q.is_read_only);
  const hasDestructive = writeQueries.some(q => q.is_destructive);

  planEl.classList.remove('hidden');
  planEl.className = 'bg-dark-800 border border-yellow-500/40 rounded-2xl p-4 space-y-3';
  planEl.innerHTML = `
    <div class="flex items-center justify-between">
      <div class="flex items-center gap-2 font-semibold text-yellow-400 text-sm">
        <i class="fas fa-list-check"></i>
        Plan correctif — ${writeQueries.length} modification(s) à appliquer
        ${hasDestructive ? '<span class="text-xs bg-red-900/30 text-red-400 border border-red-500/30 px-2 py-0.5 rounded-full"><i class="fas fa-exclamation-triangle mr-1"></i>Irréversible</span>' : ''}
      </div>
      <button onclick="aiAgentDismissPlan()" class="text-gray-500 hover:text-white text-xs"><i class="fas fa-times"></i></button>
    </div>

    <div class="space-y-2">
      ${writeQueries.map(q => `
      <div class="bg-dark-900/60 rounded-xl p-3 border border-dark-600">
        <div class="flex items-center gap-2 mb-1.5">
          <span class="text-xs bg-dark-700 text-gray-400 px-2 py-0.5 rounded font-mono">Étape ${q.step}</span>
          <span class="text-xs text-gray-300">${escapeHtml(q.description || '')}</span>
          ${q.is_destructive ? '<span class="ml-auto text-xs text-red-400"><i class="fas fa-exclamation-triangle mr-1"></i>Irréversible</span>' : ''}
        </div>
        <pre class="text-xs text-green-300 font-mono bg-dark-950/60 rounded-lg p-2.5 overflow-x-auto whitespace-pre-wrap border border-dark-700">${escapeHtml(q.sql)}</pre>
      </div>`).join('')}
    </div>

    <div class="flex gap-2 pt-1">
      <button onclick="aiAgentExecutePlan()" id="ai-exec-btn"
        class="flex-1 bg-yellow-600 hover:bg-yellow-500 text-white font-bold py-2.5 rounded-xl text-sm transition flex items-center justify-center gap-2">
        <i class="fas fa-play"></i> Appliquer les corrections
      </button>
      <button onclick="aiAgentDismissPlan()"
        class="flex-1 bg-dark-700 hover:bg-dark-600 text-gray-300 font-semibold py-2.5 rounded-xl text-sm transition border border-dark-500">
        <i class="fas fa-times mr-2"></i>Annuler
      </button>
    </div>
    <p class="text-xs text-gray-600 text-center">En cliquant "Appliquer", vous confirmez ces modifications en base de données.</p>`;
}

async function aiAgentExecutePlan() {
  if (!_aiAgentPendingPlan) return;

  const btn = document.getElementById('ai-exec-btn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>Exécution…'; }

  try {
    const res = await apiAdmin('POST', '/ai-agent/execute', {
      log_id: _aiAgentPendingPlan.log_id,
      sql_queries: _aiAgentPendingPlan.sql_queries,
      session_id: _aiAgentSession,
    });

    aiAgentDismissPlan();

    const statusIcon = res.success ? '' : '';
    const resultText = res.results.map(r =>
      r.skipped ? `Étape ${r.step} : ignorée (lecture seule)`
      : r.success ? `Étape ${r.step} : ${r.changes} modification(s)`
      : `Étape ${r.step} : Erreur — ${r.error}`
    ).join('\n');

    aiAgentAppendMessage('assistant', `${statusIcon} **${res.message}**\n\n\`\`\`\n${resultText}\n\`\`\``);
    _aiAgentHistory.push({ role: 'assistant', content: res.message });

    if (res.success){showToast('Corrections appliquées avec succès', 'success');_refreshCurrentPage();}
    else showToast('Exécution partielle — vérifiez les résultats', 'error');

  } catch (err) {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-play mr-2"></i>Appliquer les corrections'; }
    showToast(err.error || 'Erreur lors de l\'exécution', 'error');
  }
}

function aiAgentDismissPlan() {
  _aiAgentPendingPlan = null;
  const plan = document.getElementById('ai-sql-plan');
  if (plan) { plan.innerHTML = ''; plan.classList.add('hidden'); }
}

function aiAgentScrollToBottom() {
  const msgs = document.getElementById('ai-chat-messages');
  if (msgs) setTimeout(() => { msgs.scrollTop = msgs.scrollHeight; }, 50);
}

function escapeHtml(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function aiAgentMarkdown(text) {
  if (!text) return '';
  // Escape HTML sauf dans les blocs code (traités séparément)
  const parts = [];
  let last = 0;
  const codeBlockRe = /```[\w]*\n?([\s\S]*?)```/g;
  let m;
  while ((m = codeBlockRe.exec(text)) !== null) {
    // Partie texte avant le bloc code
    parts.push({ type: 'text', content: text.slice(last, m.index) });
    parts.push({ type: 'code', content: m[1] });
    last = m.index + m[0].length;
  }
  parts.push({ type: 'text', content: text.slice(last) });

  return parts.map(p => {
    if (p.type === 'code') {
      const escaped = p.content.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
      return `<pre class="bg-dark-900/80 border border-dark-700 rounded-lg p-3 my-2 overflow-x-auto text-xs font-mono text-green-300 whitespace-pre-wrap">${escaped}</pre>`;
    }
    return p.content
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
      // Inline code
      .replace(/`([^`]+)`/g, '<code class="bg-dark-700 text-purple-300 px-1.5 py-0.5 rounded text-xs font-mono">$1</code>')
      // Bold / italic
      .replace(/\*\*([^*\n]+)\*\*/g, '<strong class="text-white font-semibold">$1</strong>')
      .replace(/\*([^*\n]+)\*/g, '<em class="text-gray-300">$1</em>')
      // Titres
      .replace(/^#### (.+)$/gm, '<p class="font-bold text-gray-200 text-xs uppercase tracking-wide mt-3 mb-0.5">$1</p>')
      .replace(/^### (.+)$/gm, '<h4 class="font-bold text-white text-sm mt-3 mb-1 border-b border-dark-700 pb-0.5">$1</h4>')
      .replace(/^## (.+)$/gm, '<h3 class="font-bold text-white mt-4 mb-1">$1</h3>')
      .replace(/^# (.+)$/gm, '<h2 class="font-bold text-gold-400 text-base mt-4 mb-1">$1</h2>')
      // Listes numérotées : "1. texte"
      .replace(/^\d+\.\s+(.+)$/gm, '<div class="flex gap-2 my-0.5 pl-1"><span class="text-purple-400 flex-shrink-0 font-mono text-xs mt-0.5">›</span><span>$1</span></div>')
      // Listes à puces
      .replace(/^[•\-\*]\s+(.+)$/gm, '<div class="flex gap-2 my-0.5"><span class="text-purple-400 flex-shrink-0">•</span><span>$1</span></div>')
      // Alertes colorées
      .replace(/ALERTE([^\n]+)/g, '<div class="bg-red-900/20 border border-red-500/30 rounded-lg px-3 py-2 my-1 text-red-400 text-xs font-medium">$1</div>')
      .replace(/ATTENTION([^\n]+)/g, '<div class="bg-yellow-900/20 border border-yellow-500/30 rounded-lg px-3 py-2 my-1 text-yellow-400 text-xs">$1</div>')
      .replace(/OK([^\n]+)/g, '<div class="text-green-400 my-0.5 text-sm">$1</div>')
      .replace(/ERREUR([^\n]+)/g, '<div class="text-red-400 my-0.5">$1</div>')
      // Séparateur horizontal
      .replace(/^---$/gm, '<hr class="border-dark-700 my-2">')
      // Paragraphes et sauts de ligne
      .replace(/\n{2,}/g, '</p><p class="mt-2">')
      .replace(/\n/g, '<br>');
  }).join('');
}


